if isinstance(r, dict):
    raw = r.get('raw', '')
    lines = raw.split('\n')
    # Get last 5 lines
    for line in lines[-5:]:
        try:
            obj = json.loads(line)
            if obj.get('type') == 'assistant':
                msg = obj.get('message', {})
                content = msg.get('content', [])
