                    if c.get('type') == 'text':
                        print('ASSISTANT:', c['text'][:1000])
                    elif c.get('type') == 'thinking':
                        print('THINKING:', c['thinking'][:1000])
                    elif c.get('type') == 'tool_use':
                        print('TOOL_USE:', c['name'], json.dumps(c.get('input', {}))[:300])
            elif obj.get('type') == 'user':
                msg = obj.get('message', {})
                content = msg.get('content', [])
                for c in content:
                    if isinstance(c, dict):
                        if c.get('type') == 'tool_result':
                            ct = c.get('content', '')
                            print('TOOL_RESULT:', str(ct)[:500])
                        elif c.get('type') == 'text':
                            print('USER_TEXT:', c['text'][:500])
            elif obj.get('type') == 'result':
                print('RESULT:', json.dumps(obj)[:500])
